#include<bits/stdc++.h>
#define int long long
using namespace std;
int c,n,m,d,q;
int w[510];
int poi[510];
int vis[510];
struct node{
	int v,w;
};
vector<node> g[10001];
int dfs(int now,int st,int ed,int ans,int la){
	for(int i=0;i<g[now].size();i++){
		int v=g[now][i].v;
		int w=g[now][i].w;
		if(vis[v]) continue;
		vis[v]=1;
		if(poi[now]==0){
			if(v==ed){
				return ans+la+w;
			}
			dfs(v,st,ed,ans+la+w,w);
		}else{
			if(v==ed){
				return ans;
			}
			dfs(v,st,ed,ans,w);
		}
	}
}
signed main(){
	ios::sync_with_stdio(0);
	cin.tie(0);
	freopen("subway.in","r",stdin);
	freopen("subway.out","w",stdout);
	cin>>c>>n>>m>>d>>q;
	for(int i=1;i<=m;i++){
		cin>>w[i];
	}
	for(int i=1;i<=n;i++){
		int k;
		cin>>k;
		for(int j=1;j<=k;j++){
			int v[510],w[510];
			cin>>v[j]>>w[j];
			g[v[j]].push_back({v[j],w[j]});
			poi[v[j]]++;
			if(j>=2){
				g[v[j]].push_back({v[j-1],w[j-1]});
				g[v[j-1]].push_back({v[j],w[j]});
			}
		}
	}
	for(int i=1;i<=m;i++){
		if(poi[i]>1) poi[i]=0;
	}
	while(q--){
		memset(vis,0,sizeof(vis));
		int u,v;
		cin>>u>>v;
		vis[u]=1;
		cout<<dfs(u,u,v,w[u]+w[v]+g[u][u].w+g[v][v].w,0)<<endl;
	}
	return 0;
}
